from __future__ import annotations

import base64
import json
import zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PAYLOAD = ''


def main() -> int:
    data = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)).decode("utf-8"))
    for relative, content in data["files"].items():
        path = ROOT / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8", newline="\n")

    changelog = ROOT / "CHANGELOG.md"
    text = changelog.read_text(encoding="utf-8")
    marker = data["changelog_marker"]
    first = data["changelog_entries"][0]
    if first not in text:
        if marker not in text:
            raise ValueError("CHANGELOG.md has no Unreleased section")
        entries = "".join(f"\n- {entry}" for entry in data["changelog_entries"]) + "\n"
        changelog.write_text(
            text.replace(marker, marker + entries, 1),
            encoding="utf-8",
            newline="\n",
        )

    for relative in data["delete"]:
        (ROOT / relative).unlink(missing_ok=True)
    (ROOT / ".github" / "workflows" / "readme-simplification-once.yml").unlink(
        missing_ok=True
    )
    Path(__file__).unlink(missing_ok=True)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
